task count_Pairs(s: seq, n: int) returns (r: int)
  requires n >= 0
  requires n <= len(s)
  ensures r == n * (n - 1) / 2
{
  r := 0;
  var i: int := 0;
  while i < n
    invariant 0 <= i and i <= n
    invariant r == i * (i - 1) / 2
    decreases n - i
  {
    i := i + 1;
    r := r + i;
  }
}
